**组合（Composition）：**组合是**包含关系**，一个结构体将另一个结构体作为命名字段包含进来。

**嵌入（Embedding）：**嵌入是**语法糖**，一个结构体将另一个类型作为**匿名（未命名）字段**包含进来，字段和方法会被提升。

```Go
type Engine struct {
    Power int
}

func (e *Engine) Start() {
    fmt.Println("Engine started with power:", e.Power)
}

// 组合：Engine 作为命名字段
type Car struct {
    engine Engine  // 命名字段
    Brand  string
}

func main() {
    car := Car{
        engine: Engine{Power: 200},
        Brand: "Tesla",
    }

    // 必须通过字段名访问
    car.engine.Start()  // Engine started with power: 200
    fmt.Println(car.engine.Power)  // 200

    // 不能直接访问
    // car.Start()  // 编译错误
}
```

