```go
func main() {
    // 创建一个带有5秒超时的context
    ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
    defer cancel()

    // 定义5个接口的URL
    urls := []string{
       "https://example.com/api1",
       "https://example.com/api2",
       "https://example.com/api3",
    }

    // 使用WaitGroup来等待所有协程完成
    wg := sync.WaitGroup{}
    wg.Add(len(urls))

    // 创建一个channel来接收每个接口的响应结果
    results := make(chan string, len(urls))

    // 遍历URLs，为每个URL启动一个协程
    for _, url := range urls {
       go func(url string) {
          defer wg.Done()
          result, err := fetchAPI(ctx, url)
          if err != nil {
             // 如果context超时，直接返回，不打印错误
             if ctx.Err() == context.DeadlineExceeded {
                return
             }
             fmt.Printf("Error fetching %s: %v\n", url, err)
             return
          }
          results <- result
       }(url)
    }

    // 启动一个协程等待所有子协程完成
    go func() {
       wg.Wait()
       close(results)
    }()

    // 监听context的Done通道和results通道
    select {
    case <-ctx.Done():
       // 如果context超时，打印超时信息
       fmt.Println("Context timeout 5s exceeded, stopping all goroutines")
    case <-waitForResults(&wg):
       // 如果所有结果在5秒内返回，打印结果
       for result := range results {
          fmt.Println(result)
       }
    }
}

// fetchAPI 发送HTTP请求并返回响应内容
func fetchAPI(ctx context.Context, url string) (string, error) {
    // 模拟接口返回时间（0~7秒之间）
    rand.Seed(time.Now().UnixNano())
    delay := time.Duration(rand.Intn(8)) * time.Second // 生成0~7秒的随机延迟
    fmt.Printf("Fetching %s with delay: %v\n", url, delay)
    time.Sleep(delay)

    // 检查context是否已经超时或取消
    //当 context 超时后，所有子协程会通过 ctx.Err() 检测到超时，并直接返回，不再继续执行
    if ctx.Err() != nil {
       return "", ctx.Err()
    }
    //时间到后，模拟返回
    return fmt.Sprintf("get %s 's resp", url), nil
}

// waitForResults 等待所有结果返回，并返回一个通道
func waitForResults(wg *sync.WaitGroup) chan struct{} {
    done := make(chan struct{})
    go func() {
       wg.Wait()
       close(done)
    }()
    return done
}
```

q0366.answer:
**分析**

首先要明确协程池的作用，应该有哪些角色，怎么添加任务，怎么获取任务，以及worker的大小怎么限制

参考《golang学习与面试》<cite doc-id="wikcnZ2569bGZ9HbMpmoN0Ljsve" file-type="wiki" title="协程池" type="doc"></cite>（该文档实现里，main函数有问题）

```go
// Task 结构体用于封装具体的任务逻辑
type Task struct {
    f func() error // 具体的任务逻辑
}

// NewTask 函数用于创建一个新的 Task 实例
func NewTask(funcArg func() error) *Task {
    return &Task{
       f: funcArg, // 将传入的任务函数赋值给 Task 结构体的 f 字段
    }
}

// Pool 结构体表示一个协程池，包含运行中的 worker 数量、worker 容量、任务通道和互斥锁
type Pool struct {
    RunningWorkers int64      // 运行着的worker数量
    Capacity       int64      // 协程池worker容量
    JobCh          chan *Task // 用于worker取任务
    sync.Mutex                // 用于保护并发访问 Pool 的字段
    wg             sync.WaitGroup
}

// NewPool 函数用于创建一个新的协程池实例
func NewPool(capacity int64, taskNum int) *Pool {
    return &Pool{
       Capacity: capacity,                  // 设置协程池的最大worker数量
       JobCh:    make(chan *Task, taskNum), // 创建一个缓冲通道，大小为taskNum
    }
}

// GetCap 返回协程池的容量
func (p *Pool) GetCap() int64 {
    return p.Capacity
}

// incRunning 原子地增加 RunningWorkers 的值
func (p *Pool) incRunning() {
    atomic.AddInt64(&p.RunningWorkers, 1)
}

// decRunning 原子地减少 RunningWorkers 的值
func (p *Pool) decRunning() {
    atomic.AddInt64(&p.RunningWorkers, -1)
}

// GetRunningWorkers 返回当前正在运行的 worker 数量
func (p *Pool) GetRunningWorkers() int64 {
    return atomic.LoadInt64(&p.RunningWorkers)
}

// run 启动一个新的 worker goroutine 处理任务
func (p *Pool) run() {
    p.incRunning()
    go func() {
       defer func() {
          p.decRunning()
       }()
       for task := range p.JobCh { // 循环从 JobCh 中取出任务并执行
          task.f()
          p.wg.Done()
       }
    }()
}

// AddTask 向协程池添加一个任务
func (p *Pool) AddTask(task *Task) {
    p.Lock()
    // 如果当前运行的worker数小于最大容量，则启动新的worker
    if p.GetRunningWorkers() < p.GetCap() {
       p.run()
    }
    p.Unlock()

    // 将任务推入队列，等待消费
    p.JobCh <- task
}

func main() {
    pool := NewPool(3, 10) // 创建一个容量为3，任务通道大小为10的协程池
    for i := 0; i < 20; i++ { // 循环添加20个任务到协程池中
       pool.wg.Add(1) // 每次循环前增加WaitGroup计数
       x := i
       pool.AddTask(NewTask(func() error {
          fmt.Printf("I am Task %d \n", x) // 打印任务编号
          return nil
       }))
    }

    pool.wg.Wait()    // 等待所有任务完成
    close(pool.JobCh) // 关闭任务通道，通知所有worker没有更多任务需要处理
}
```

